 if(e.kind==='guardian'){ctx.save();ctx.translate(x,y-44);ctx.rotate(time);ctx.strokeStyle=e.vulnerable?'#caffb7':'#b7baff';ctx.lineWidth=5;ctx.beginPath();ctx.ellipse(0,0,68,23,.4,0,7);ctx.stroke();ctx.restore()}
