 for(let w of s.walls){if(!visible(w))continue;round(w.x,w.y,w.w,w.h,16,'#244a61');round(w.x+8,w.y+8,w.w-16,w.h-16,10,'#122c43');ctx.strokeStyle=theme.accent+'44';ctx.lineWidth=4;for(let x=w.x+20;x<w.x+w.w;x+=44){ctx.beginPath();ctx.moveTo(x,w.y+10);ctx.lineTo(x,w.y+w.h-10);ctx.stroke()}if(w.kind==='tunnel')text('▰',w.x+w.w/2,w.y+w.h-25,28,theme.accent,'center');ctx.strokeStyle='#bafccf66';ctx.lineWidth=2;ctx.strokeRect(w.x-5,w.y+w.h+1,w.w+10,28)}
 for(let w of s.winds){if(w.decor||!visible(w))continue;let g=ctx.createLinearGradient(w.x,0,w.x+w.w,0);g.addColorStop(0,'#8dfff200');g.addColorStop(.5,'#8dfff21b');g.addColorStop(1,'#8dfff200');ctx.fillStyle=g;ctx.fillRect(w.x,w.y,w.w,w.h);ctx.strokeStyle='#b7fff65e';ctx.lineWidth=2;for(let j=0;j<15;j++){let y=w.y+w.h-((time*120+j*31)%w.h),x=w.x+25+(j*37)%(w.w-40);ctx.beginPath();ctx.moveTo(x,y+18);ctx.lineTo(x,y);ctx.lineTo(x-4,y+5);ctx.stroke()}round(w.x+10,w.y+w.h-12,w.w-20,12,4,'#517d8c');text('↑  ○  ↑',w.x+w.w/2,w.y+w.h-25,21,'#a9fff1','center')}
 for(let a of s.springs){round(a.x+a.w*.4,a.y-25,a.w*.2,25,5,'#f0dcdb');ctx.fillStyle='#c59bff';ctx.beginPath();ctx.ellipse(a.x+a.w/2,a.y-25,a.w*.65,20,0,Math.PI,0);ctx.fill();ctx.fillStyle='#ffefcd';for(let j=0;j<3;j++){ctx.beginPath();ctx.arc(a.x+15+j*16,a.y-34,4,0,7);ctx.fill()}}
 for(let b of s.buttons){round(b.x-31,b.y-9,62,9,4,'#153a49');round(b.x-24,b.y-(b.pressed?5:14),48,b.pressed?5:14,4,b.pressed?'#a8ffc2':'#b2f978');if(!b.pressed)text('↓',b.x,b.y-26,23,'#baffae','center')}
 for(let d of s.doors){if(!visible(d))continue;ctx.save();ctx.globalAlpha=d.open?.15:1;round(d.x,d.y,d.w,d.h,8,'#3a6477');round(d.x+7,d.y+8,d.w-14,d.h-16,3,d.color||(d.kind==='button'?'#8bf8b6':'#ffa6bc'));if(!d.open){for(let y=d.y+25;y<d.y+d.h;y+=38)round(d.x+3,y,d.w-6,5,2,'#183748');text(d.symbol||(d.kind==='button'?'●':'⚔'),d.x+d.w/2,d.y+50,22,'#edffff','center')}ctx.restore()}
 for(let g of s.gravitySwitches){ctx.save();ctx.translate(g.x,g.y);ctx.rotate(time*.5);ctx.strokeStyle=g.active?'#a4ecca':'#cab0ff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,25,0,7);ctx.stroke();ctx.restore();text('✦',g.x,g.y+10,30,g.active?'#adffcf':'#d9c5ff','center')}
