 ctx.save();ctx.fillStyle='#3a203e';ctx.strokeStyle='#d5a3b866';ctx.lineWidth=1.5;
 for(let side of [-1,1]){ctx.beginPath();ctx.moveTo(side*r*.82,r*.5);ctx.lineTo(side*r*1.2,r*.72);ctx.lineTo(side*r*1.05,r*.1);ctx.closePath();ctx.fill();ctx.stroke()}
 ctx.fillStyle=o.kind==='jumper'?'#e0b188':'#ad6f93';for(let i=0;i<3;i++){let x=(-.5+i*.5)*r;ctx.beginPath();ctx.moveTo(x-r*.12,-r*.8);ctx.lineTo(x,-r*(1.08+(i%2)*.2));ctx.lineTo(x+r*.14,-r*.8);ctx.fill()}
 if(o.kind==='jumper'){ctx.strokeStyle='#b98f9a';ctx.lineWidth=r*.14;for(let side of [-1,1]){ctx.beginPath();ctx.moveTo(side*r*.75,r*.5);ctx.lineTo(side*r*1.17,r*.8);ctx.lineTo(side*r*.85,r*.89);ctx.stroke()}}
 if(o.kind==='flyer'){ctx.fillStyle='#563754';for(let side of [-1,1]){ctx.beginPath();ctx.moveTo(side*r*.8,-r*.25);ctx.quadraticCurveTo(side*r*1.65,-r*1.3+Math.sin(t*15)*r*.2,side*r*2,-r*.55);ctx.lineTo(side*r*1.55,r*.1);ctx.lineTo(side*r*1.1,r*.15);ctx.closePath();ctx.fill()}}
 ctx.fillStyle='#ffd79a';for(let ex of [-.36,.36]){ctx.beginPath();ctx.arc(ex*r,-r*.12,r*.115,0,7);ctx.fill();ctx.fillStyle='#2a2035';ctx.fillRect(ex*r-r*.035,-r*.29,r*.07,r*.31);ctx.fillStyle='#ffd79a'}
