function platformMaterial(f,theme,world){
 const organic=[1,2,4,5].includes(world),left=Math.max(f.x,cam.x-100),right=Math.min(f.x+f.w,cam.x+viewW+100);
 ctx.save();let g=ctx.createLinearGradient(0,f.y,0,f.y+f.h);g.addColorStop(0,organic?theme.stone:'#4d7380');g.addColorStop(.13,organic?theme.ground||theme.stone:'#2c4b5c');g.addColorStop(1,organic?'#263844':'#122a3b');ctx.fillStyle=g;ctx.beginPath();ctx.roundRect(f.x,f.y,f.w,f.h,6);ctx.fill();
 ctx.strokeStyle='#c4f2ee66';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(f.x+5,f.y+2);ctx.lineTo(f.x+f.w-5,f.y+2);ctx.stroke();ctx.fillStyle=theme.accent;ctx.globalAlpha=.65;ctx.fillRect(f.x+5,f.y+3,f.w-10,3);ctx.globalAlpha=1;
 if(organic){for(let x=Math.floor(left/39)*39;x<right;x+=39){let q=Math.sin(x*2.37);ctx.strokeStyle='#0a1d2b66';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(x,f.y+10);ctx.lineTo(x+8,f.y+17);ctx.lineTo(x+3,f.y+Math.min(32,f.h-2));ctx.stroke();if(world===1){ctx.fillStyle='#89dca577';ctx.beginPath();ctx.ellipse(x+7,f.y+7,10,3,q,0,7);ctx.fill()}if(world===4&&f.h<50){ctx.fillStyle='#b4eaff77';ctx.beginPath();ctx.moveTo(x,f.y+f.h);ctx.lineTo(x+4,f.y+f.h+12);ctx.lineTo(x+9,f.y+f.h);ctx.fill()}}}
 else{let stride=f.h>50?96:70;for(let x=Math.floor(left/stride)*stride;x<right;x+=stride){ctx.strokeStyle='#6d95a044';ctx.lineWidth=1;ctx.strokeRect(x+4,f.y+9,stride-8,Math.min(f.h-14,58));for(let px of [x+10,x+stride-10]){ctx.fillStyle='#0b1a29';ctx.beginPath();ctx.arc(px,f.y+12,2.8,0,7);ctx.fill();ctx.fillStyle='#89a5ac';ctx.beginPath();ctx.arc(px-.6,f.y+11,1,0,7);ctx.fill()}if(f.kind==='ground'){round(x+18,f.y+26,stride-36,13,3,'#102a3c');ctx.fillStyle='#72ada652';for(let j=0;j<4;j++)ctx.fillRect(x+24+j*8,f.y+30,3,5)}}}
 if(f.kind==='crumble'){ctx.strokeStyle='#f2bf86';ctx.lineWidth=2;for(let x=left+15;x<right;x+=40){ctx.beginPath();ctx.moveTo(x,f.y);ctx.lineTo(x-7,f.y+11);ctx.lineTo(x+4,f.y+f.h);ctx.stroke()}}
 if(f.kind==='ground'&&!organic){ctx.strokeStyle='#07121e';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(left,f.y+f.h-12);ctx.lineTo(right,f.y+f.h-12);ctx.stroke();ctx.strokeStyle='#53757e77';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(left,f.y+f.h-15);ctx.lineTo(right,f.y+f.h-15);ctx.stroke()}
 ctx.restore();
}

function frame(t){if(!last)last=t;acc+=Math.min(.075,(t-last)/1000);last=t;while(acc>=C.DT){tick(C.DT);acc-=C.DT}render();requestAnimationFrame(frame)}
function inputDown(k,repeated=false){if(mode!=='play')return;physicallyHeld.add(k);if(repeated||blockedUntilRelease.has(k))return;if(k==='jump')jumpQueued=true;else keys[k]=true}
function inputUp(k){physicallyHeld.delete(k);blockedUntilRelease.delete(k);if(k!=='jump')keys[k]=false}
document.querySelectorAll('[data-key]').forEach(b=>{let k=b.dataset.key;b.addEventListener('pointerdown',e=>{if(mode!=='play')return;e.preventDefault();b.setPointerCapture(e.pointerId);inputDown(k);if(!blockedUntilRelease.has(k))b.classList.add('held')});let up=()=>{inputUp(k);b.classList.remove('held')};b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('lostpointercapture',up)});
window.addEventListener('keydown',e=>{let k={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'jump',' ':'jump',w:'jump'}[e.key];if(k){e.preventDefault();inputDown(k,e.repeat)}if(!e.repeat&&mode==='play'){if(e.key==='1'||e.key==='s')C.setForm(state,'flat');if(e.key==='2'||e.key==='f')C.setForm(state,'bubble');if(e.key==='e'||e.key==='Enter')interactQueued=true;if(e.key==='h')requestHint()}if(e.key==='Escape')pause()});window.addEventListener('keyup',e=>{let k={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'jump',' ':'jump',w:'jump'}[e.key];if(k)inputUp(k)});window.addEventListener('blur',()=>{for(const k of physicallyHeld)blockedUntilRelease.add(k);clearKeys();pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearKeys();pause()}});
$('flat').onclick=()=>{if(mode==='play'){C.setForm(state,'flat');events();updateHud()}};$('bubble').onclick=()=>{if(mode==='play'){C.setForm(state,'bubble');events();updateHud()}};$('interact').onclick=()=>{if(mode==='play')interactQueued=true};$('help').onclick=requestHint;$('intro').onclick=()=>start(1);$('play').onclick=()=>start(saved.unlocked);$('choose').onclick=map;$('back').onclick=home;$('dress').onclick=wardrobe;$('dressBack').onclick=home;$('pause').onclick=pause;$('sound').onclick=()=>{saved.muted=!saved.muted;persist();if(saved.muted&&window.speechSynthesis)speechSynthesis.cancel();else tone();updateHud()};requestAnimationFrame(frame);






